const { PDFDocument, rgb } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const font = await doc.embedFont(fs.readFileSync('/usr/share/fonts/workspacex/NotoSansSC-Common.otf'));

  const pageW = 595, pageH = 842;
  const ml = 50, mr = 50, mt = 60;
  const contentW = pageW - ml - mr;

  const titleSize = 22;
  const sectionSize = 14;
  const bodySize = 11;
  const lineH = 18;

  const sections = [
    {
      title: '文档与办公',
      items: [
        '创建和编辑 Word、Excel、PowerPoint、PDF 文件',
        '解析上传的 Office / CSV / PDF 原件，提取表格与关键内容',
        '生成带图表的数据分析报告与可视化图表',
      ],
    },
    {
      title: '会议与沟通',
      items: [
        '音频转写、会议纪要提炼（决策 + 行动项）',
        '会议准备：背景材料、议程、预读清单',
        '撰写内部公告、领导更新、FAQ、项目状态简报',
      ],
    },
    {
      title: '研究与知识',
    },
  ];

  // We'll build content lines manually to keep script short
  const lines = [];

  // Title
  lines.push({ text: 'AI 助手能力总结', size: titleSize, color: rgb(0.15, 0.35, 0.65), spacingAfter: 8 });
  lines.push({ text: '以下是我当前可以为你完成的主要工作类别。', size: bodySize, spacingAfter: 20 });

  // Section 1
  lines.push({ text: '一、文档与办公', size: sectionSize, color: rgb(0.15, 0.35, 0.65), spacingAfter: 4 });
  lines.push({ text: '• 创建和编辑 Word、Excel、PowerPoint、PDF 文件', size: bodySize });
  lines.push({ text: '• 解析上传的 Office / CSV / PDF 原件，提取表格与关键内容', size: bodySize });
  lines.push({ text: '• 生成带图表的数据分析报告与可视化图表', size: bodySize, spacingAfter: 14 });

  // Section 2
  lines.push({ text: '二、会议与沟通', size: sectionSize, color: rgb(0.15, 0.35, 0.65), spacingAfter: 4 });
  lines.push({ text: '• 音频转写、会议纪要提炼（决策 + 行动项）', size: bodySize });
  lines.push({ text: '• 会议准备：背景材料、议程、预读清单', size: bodySize });
  lines.push({ text: '• 撰写内部公告、领导更新、FAQ、项目状态简报', size: bodySize, spacingAfter: 14 });

  // Section 3
  lines.push({ text: '三、研究与知识', size: sectionSize, color: rgb(0.15, 0.35, 0.65), spacingAfter: 4 });
  lines.push({ text: '• 联网检索公开资料，形成带引用的研究报告', size: bodySize });
  lines.push({ text: '• 基于组织内部资料回答政策 / 项目知识问题', size: bodySize });
  lines.push({ text: '• 综合多场访谈记录，提炼主题、引文与反例', size: bodySize, spacingAfter: 14 });

  // Section 4
  lines.push({ text: '四、设计与创意', size: sectionSize, color: rgb(0.15, 0.35, 0.65), spacingAfter: 4 });
  lines.push({ text: '• 制作海报、配图等静态视觉作品', size: bodySize });
  lines.push({ text: '• 生成可交互的自包含网页产物（Web Artifact）', size: bodySize });
  lines.push({ text: '• 绘制流程图、架构图、MAAU 画布等 Mermaid 图表', size: bodySize, spacingAfter: 14 });

  // Section 5
  lines.push({ text: '五、用户研究', size: sectionSize, color: rgb(0.15, 0.35, 0.65), spacingAfter: 4 });
  lines.push({ text: '• 制定研究计划、招募条件与中立访谈提纲', size: bodySize });
  lines.push({ text: '• 综合分析访谈转录，输出可定位的发现摘要', size: bodySize, spacingAfter: 14 });

  // Section 6
  lines.push({ text: '六、系统与自动化', size: sectionSize, color: rgb(0.15, 0.35, 0.65), spacingAfter: 4 });
  lines.push({ text: '• 在沙箱中执行 Shell / Python / Node.js 脚本', size: bodySize });
  lines.push({ text: '• 读写文件系统、搜索代码与内容', size: bodySize });
  lines.push({ text: '• 将重复工作流整理为可复用的技能草稿包', size: bodySize, spacingAfter: 20 });

  // Footer note
  lines.push({ text: '如需了解某项能力的具体用法或限制，请直接向我提问。', size: bodySize, color: rgb(0.4, 0.4, 0.4) });

  const page = doc.addPage([pageW, pageH]);
  let y = pageH - mt;

  for (const ln of lines) {
    const sz = ln.size || bodySize;
    const opts = { x: ml, y, size: sz, font };
    if (ln.color) opts.color = ln.color;
    page.drawText(ln.text, opts);
    y -= sz + (ln.spacingAfter !== undefined ? ln.spacingAfter : 6);
  }

  // Divider line under title
  page.drawLine({
    start: { x: ml, y: pageH - mt - titleSize - 4 },
    end: { x: pageW - mr, y: pageH - mt - titleSize - 4 },
    thickness: 0.8,
    color: rgb(0.7, 0.7, 0.7),
  });

  const bytes = await doc.save();
  fs.writeFileSync('/workspace/capabilities-summary.pdf', bytes);
  console.log('PDF generated: /workspace/capabilities-summary.pdf');
})()...[4061 chars total]
